import test from 'node:test';
import assert from 'node:assert/strict';
import {square,quad} from './math.mjs';
test('square positive control',()=>assert.equal(square(3),9));
test('quad positive regression',()=>assert.equal(quad(2),16));
test('quad zero regression',()=>assert.equal(quad(0),0));
test('quad negative regression',()=>assert.equal(quad(-3),81));
